impl ByteSoftmaxModel {
    pub fn new(weights: Vec<i8>) -> Result<Self, TrainError> {
        if weights.len() != BYTE_VOCAB * BYTE_D_MODEL {
            return Err(TrainError::InvalidModel("wrong byte-softmax weight count"));
        }
        Ok(Self { weights })
    }

    pub fn weight_hash(&self) -> u64 {
        hash_i8_slice(&self.weights)
    }

    pub fn try_to_bytes(&self) -> Result<Vec<u8>, TrainError> {
        let mut out = Vec::with_capacity(checked_model_capacity(32, &[self.weights.len()])?);
        out.extend_from_slice(BYTE_SOFTMAX_MODEL_MAGIC);
        out.extend_from_slice(&checked_u32(BYTE_VOCAB, "byte vocab exceeds u32")?.to_le_bytes());
        out.extend_from_slice(
            &checked_u32(BYTE_D_MODEL, "byte d_model exceeds u32")?.to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u64(self.weights.len(), "byte weight count exceeds u64")?.to_le_bytes(),
        );
        out.extend_from_slice(&self.weight_hash().to_le_bytes());
        out.extend(self.weights.iter().map(|&weight| weight as u8));
        Ok(out)
    }

    pub fn to_bytes(&self) -> Vec<u8> {
        self.try_to_bytes()
            .expect("byte softmax model should fit on-disk format")
    }

    pub fn from_bytes(bytes: &[u8]) -> Result<Self, TrainError> {
        let header_len = BYTE_SOFTMAX_MODEL_MAGIC.len() + 4 + 4 + 8 + 8;
        if bytes.len() < header_len {
            return Err(TrainError::InvalidModel("artifact too short"));
        }
        if &bytes[..BYTE_SOFTMAX_MODEL_MAGIC.len()] != BYTE_SOFTMAX_MODEL_MAGIC {
            return Err(TrainError::InvalidModel("bad magic"));
        }

        let mut offset = BYTE_SOFTMAX_MODEL_MAGIC.len();
        let vocab = read_u32_le(bytes, &mut offset)?;
        let d_model = read_u32_le(bytes, &mut offset)?;
        let weight_count = read_u64_le(bytes, &mut offset)? as usize;
        let expected_hash = read_u64_le(bytes, &mut offset)?;

        if vocab as usize != BYTE_VOCAB || d_model as usize != BYTE_D_MODEL {
            return Err(TrainError::InvalidModel("shape mismatch"));
        }
        if weight_count != BYTE_VOCAB * BYTE_D_MODEL {
            return Err(TrainError::InvalidModel("weight count mismatch"));
        }
        if bytes.len() != offset + weight_count {
            return Err(TrainError::InvalidModel("artifact length mismatch"));
        }

        let weights = bytes[offset..]
            .iter()
            .map(|&byte| byte as i8)
            .collect::<Vec<_>>();
        let model = Self::new(weights)?;
        if model.weight_hash() != expected_hash {
            return Err(TrainError::InvalidModel("weight hash mismatch"));
        }
        Ok(model)
    }
}

impl ByteEmbedSoftmaxModel {
    pub fn new(
        seq_len: usize,
        embeddings: Vec<i16>,
        output_weights: Vec<i8>,
    ) -> Result<Self, TrainError> {
        if seq_len == 0 || !seq_len.is_power_of_two() {
            return Err(TrainError::InvalidModel("bad context seq_len"));
        }
        if embeddings.len() != BYTE_VOCAB * BYTE_EMBED_DIM {
            return Err(TrainError::InvalidModel("wrong byte embedding count"));
        }
        if output_weights.len() != BYTE_VOCAB * BYTE_EMBED_D_MODEL {
            return Err(TrainError::InvalidModel("wrong byte output weight count"));
        }
        Ok(Self {
            seq_len,
            embeddings,
            output_weights,
        })
    }

    pub fn embedding_hash(&self) -> u64 {
        hash_i16_slice(&self.embeddings)
    }

    pub fn output_weight_hash(&self) -> u64 {
        hash_i8_slice(&self.output_weights)
    }

    pub fn model_hash(&self) -> u64 {
        let mut hasher = StableHasher::new();
        hasher.update_usize(self.seq_len);
        hasher.update_i16_slice(&self.embeddings);
        hasher.update_i8_slice(&self.output_weights);
        hasher.finish()
    }

    pub fn try_to_bytes(&self) -> Result<Vec<u8>, TrainError> {
        let embedding_bytes =
            checked_i16_tensor_bytes(self.embeddings.len(), "byte embedding bytes overflow")?;
        let mut out = Vec::with_capacity(checked_model_capacity(
            56,
            &[embedding_bytes, self.output_weights.len()],
        )?);
        out.extend_from_slice(BYTE_EMBED_SOFTMAX_MODEL_MAGIC);
        out.extend_from_slice(&checked_u32(BYTE_VOCAB, "byte vocab exceeds u32")?.to_le_bytes());
        out.extend_from_slice(
            &checked_u32(BYTE_EMBED_DIM, "byte embed dim exceeds u32")?.to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u32(self.seq_len, "byte seq_len exceeds u32")?.to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u64(self.embeddings.len(), "byte embedding count exceeds u64")?.to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u64(
                self.output_weights.len(),
                "byte output weight count exceeds u64",
            )?
            .to_le_bytes(),
        );
        out.extend_from_slice(&self.embedding_hash().to_le_bytes());
        out.extend_from_slice(&self.output_weight_hash().to_le_bytes());
        for &embedding in self.embeddings.iter() {
            out.extend_from_slice(&embedding.to_le_bytes());
        }
        out.extend(self.output_weights.iter().map(|&weight| weight as u8));
        Ok(out)
    }

    pub fn to_bytes(&self) -> Vec<u8> {
        self.try_to_bytes()
            .expect("byte embed-softmax model should fit on-disk format")
    }

    pub fn from_bytes(bytes: &[u8]) -> Result<Self, TrainError> {
        let header_len = BYTE_EMBED_SOFTMAX_MODEL_MAGIC.len() + 4 + 4 + 4 + 8 + 8 + 8 + 8;
        if bytes.len() < header_len {
            return Err(TrainError::InvalidModel("artifact too short"));
        }
        if &bytes[..BYTE_EMBED_SOFTMAX_MODEL_MAGIC.len()] != BYTE_EMBED_SOFTMAX_MODEL_MAGIC {
            return Err(TrainError::InvalidModel("bad magic"));
        }

        let mut offset = BYTE_EMBED_SOFTMAX_MODEL_MAGIC.len();
        let vocab = read_u32_le(bytes, &mut offset)?;
        let embed_dim = read_u32_le(bytes, &mut offset)?;
        let seq_len = read_u32_le(bytes, &mut offset)? as usize;
        let embedding_count = read_u64_le(bytes, &mut offset)? as usize;
        let weight_count = read_u64_le(bytes, &mut offset)? as usize;
        let expected_embedding_hash = read_u64_le(bytes, &mut offset)?;
        let expected_weight_hash = read_u64_le(bytes, &mut offset)?;

        if vocab as usize != BYTE_VOCAB || embed_dim as usize != BYTE_EMBED_DIM {
            return Err(TrainError::InvalidModel("shape mismatch"));
        }
        if seq_len == 0 || !seq_len.is_power_of_two() {
            return Err(TrainError::InvalidModel("bad context seq_len"));
        }
        if embedding_count != BYTE_VOCAB * BYTE_EMBED_DIM {
            return Err(TrainError::InvalidModel("embedding count mismatch"));
        }
        if weight_count != BYTE_VOCAB * BYTE_EMBED_D_MODEL {
            return Err(TrainError::InvalidModel("weight count mismatch"));
        }

        let embedding_bytes = embedding_count
            .checked_mul(2)
            .ok_or(TrainError::InvalidModel("embedding length overflow"))?;
        let embedding_end = offset
            .checked_add(embedding_bytes)
            .ok_or(TrainError::InvalidModel("embedding offset overflow"))?;
        let weight_end = embedding_end
            .checked_add(weight_count)
            .ok_or(TrainError::InvalidModel("weight offset overflow"))?;
        if bytes.len() != weight_end {
            return Err(TrainError::InvalidModel("artifact length mismatch"));
        }

        let mut embeddings = Vec::with_capacity(embedding_count);
        for chunk in bytes[offset..embedding_end].chunks_exact(2) {
            embeddings.push(i16::from_le_bytes(
                chunk
                    .try_into()
                    .map_err(|_| TrainError::InvalidModel("bad embedding"))?,
            ));
        }
        let output_weights = bytes[embedding_end..weight_end]
            .iter()
            .map(|&byte| byte as i8)
            .collect::<Vec<_>>();
        let model = Self::new(seq_len, embeddings, output_weights)?;
        if model.embedding_hash() != expected_embedding_hash {
            return Err(TrainError::InvalidModel("embedding hash mismatch"));
        }
        if model.output_weight_hash() != expected_weight_hash {
            return Err(TrainError::InvalidModel("weight hash mismatch"));
        }
        Ok(model)
    }
}

impl LexemeEmbeddingModel {
    pub fn new(
        vocab_size: usize,
        embedding_dim: usize,
        embeddings: Vec<i16>,
    ) -> Result<Self, TrainError> {
        if vocab_size == 0 || embedding_dim == 0 {
            return Err(TrainError::InvalidModel("bad lexeme embedding shape"));
        }
        if embeddings.len()
            != vocab_size
                .checked_mul(embedding_dim)
                .ok_or(TrainError::InvalidModel("lexeme embedding count overflow"))?
        {
            return Err(TrainError::InvalidModel("wrong lexeme embedding count"));
        }
        Ok(Self {
            vocab_size,
            embedding_dim,
            embeddings,
        })
    }

    pub fn embedding_hash(&self) -> u64 {
        hash_i16_slice(&self.embeddings)
    }

    pub fn model_hash(&self) -> u64 {
        let mut hasher = StableHasher::new();
        hasher.update_usize(self.vocab_size);
        hasher.update_usize(self.embedding_dim);
        hasher.update_i16_slice(&self.embeddings);
        hasher.finish()
    }

    pub fn try_to_bytes(&self) -> Result<Vec<u8>, TrainError> {
        let embedding_bytes =
            checked_i16_tensor_bytes(self.embeddings.len(), "lexeme embedding bytes overflow")?;
        let mut out = Vec::with_capacity(checked_model_capacity(36, &[embedding_bytes])?);
        out.extend_from_slice(LEXEME_EMBEDDING_MODEL_MAGIC);
        out.extend_from_slice(
            &checked_u32(self.vocab_size, "lexeme vocab_size exceeds u32")?.to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u32(self.embedding_dim, "lexeme embedding_dim exceeds u32")?.to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u64(self.embeddings.len(), "lexeme embedding count exceeds u64")?
                .to_le_bytes(),
        );
        out.extend_from_slice(&self.embedding_hash().to_le_bytes());
        for &embedding in self.embeddings.iter() {
            out.extend_from_slice(&embedding.to_le_bytes());
        }
        Ok(out)
    }

    pub fn to_bytes(&self) -> Vec<u8> {
        self.try_to_bytes()
            .expect("lexeme embedding model should fit on-disk format")
    }

    pub fn from_bytes(bytes: &[u8]) -> Result<Self, TrainError> {
        let header_len = LEXEME_EMBEDDING_MODEL_MAGIC.len() + 4 + 4 + 8 + 8;
        if bytes.len() < header_len {
            return Err(TrainError::InvalidModel("artifact too short"));
        }
        if &bytes[..LEXEME_EMBEDDING_MODEL_MAGIC.len()] != LEXEME_EMBEDDING_MODEL_MAGIC {
            return Err(TrainError::InvalidModel("bad magic"));
        }

        let mut offset = LEXEME_EMBEDDING_MODEL_MAGIC.len();
        let vocab_size = read_u32_le(bytes, &mut offset)? as usize;
        let embedding_dim = read_u32_le(bytes, &mut offset)? as usize;
        let embedding_count = read_u64_le(bytes, &mut offset)? as usize;
        let expected_embedding_hash = read_u64_le(bytes, &mut offset)?;
        let embedding_bytes = embedding_count
            .checked_mul(2)
            .ok_or(TrainError::InvalidModel("embedding length overflow"))?;
        let embedding_end = offset
            .checked_add(embedding_bytes)
            .ok_or(TrainError::InvalidModel("embedding offset overflow"))?;
        if bytes.len() != embedding_end {
            return Err(TrainError::InvalidModel("artifact length mismatch"));
        }

        let mut embeddings = Vec::with_capacity(embedding_count);
        for chunk in bytes[offset..embedding_end].chunks_exact(2) {
            embeddings.push(i16::from_le_bytes(
                chunk
                    .try_into()
                    .map_err(|_| TrainError::InvalidModel("bad embedding"))?,
            ));
        }
        let model = Self::new(vocab_size, embedding_dim, embeddings)?;
        if model.embedding_hash() != expected_embedding_hash {
            return Err(TrainError::InvalidModel("embedding hash mismatch"));
        }
        Ok(model)
    }
}

impl LexemeSoftmaxModel {
    pub fn new(
        seq_len: usize,
        vocab_size: usize,
        embedding_dim: usize,
        embeddings: Vec<i16>,
        output_weights: Vec<i8>,
    ) -> Result<Self, TrainError> {
        Self::new_with_context_features(
            seq_len,
            vocab_size,
            embedding_dim,
            LexemeContextFeatures::Mean,
            embeddings,
            output_weights,
        )
    }

    pub fn new_with_context_features(
        seq_len: usize,
        vocab_size: usize,
        embedding_dim: usize,
        context_features: LexemeContextFeatures,
        embeddings: Vec<i16>,
        output_weights: Vec<i8>,
    ) -> Result<Self, TrainError> {
        Self::new_with_context_features_and_hidden(
            seq_len,
            vocab_size,
            embedding_dim,
            context_features,
            0,
            embeddings,
            Vec::new(),
            output_weights,
        )
    }

    #[allow(clippy::too_many_arguments)]
    pub fn new_with_context_features_and_hidden(
        seq_len: usize,
        vocab_size: usize,
        embedding_dim: usize,
        context_features: LexemeContextFeatures,
        hidden_dim: usize,
        embeddings: Vec<i16>,
        hidden_weights: Vec<i8>,
        output_weights: Vec<i8>,
    ) -> Result<Self, TrainError> {
        Self::new_with_context_features_hidden_and_layout(
            seq_len,
            vocab_size,
            embedding_dim,
            context_features,
            hidden_dim,
            default_lexeme_softmax_head_layout(hidden_dim, 0),
            embeddings,
            hidden_weights,
            output_weights,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn new_with_context_features_hidden_and_layout(
        seq_len: usize,
        vocab_size: usize,
        embedding_dim: usize,
        context_features: LexemeContextFeatures,
        hidden_dim: usize,
        head_layout: LexemeSoftmaxHeadLayout,
        embeddings: Vec<i16>,
        hidden_weights: Vec<i8>,
        output_weights: Vec<i8>,
    ) -> Result<Self, TrainError> {
        Self::new_with_context_features_hidden_layout_and_adapter_shift(
            seq_len,
            vocab_size,
            embedding_dim,
            context_features,
            hidden_dim,
            head_layout,
            0,
            embeddings,
            hidden_weights,
            output_weights,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn new_with_context_features_hidden_layout_and_adapter_shift(
        seq_len: usize,
        vocab_size: usize,
        embedding_dim: usize,
        context_features: LexemeContextFeatures,
        hidden_dim: usize,
        head_layout: LexemeSoftmaxHeadLayout,
        adapter_logit_shift: u8,
        embeddings: Vec<i16>,
        hidden_weights: Vec<i8>,
        output_weights: Vec<i8>,
    ) -> Result<Self, TrainError> {
        if seq_len == 0 || !seq_len.is_power_of_two() || vocab_size == 0 || embedding_dim == 0 {
            return Err(TrainError::InvalidModel("bad lexeme softmax shape"));
        }
        if adapter_logit_shift > 0 && head_layout != LexemeSoftmaxHeadLayout::ResidualAdapter {
            return Err(TrainError::InvalidModel(
                "adapter shift requires residual adapter head",
            ));
        }
        if head_layout == LexemeSoftmaxHeadLayout::ResidualAdapter && adapter_logit_shift == 0 {
            return Err(TrainError::InvalidModel(
                "residual adapter head requires adapter shift",
            ));
        }
        if usize::from(LEXEME_LOGIT_RIGHT_SHIFT).saturating_add(usize::from(adapter_logit_shift))
            > usize::from(MAX_RIGHT_SHIFT)
        {
            return Err(TrainError::InvalidModel("adapter shift too large"));
        }
        let embedding_count = vocab_size
            .checked_mul(embedding_dim)
            .ok_or(TrainError::InvalidModel("lexeme embedding count overflow"))?;
        let d_model = lexeme_context_d_model(embedding_dim, seq_len, context_features)
            .map_err(|_| TrainError::InvalidModel("lexeme d_model overflow"))?;
        let hidden_weight_count =
            hidden_dim
                .checked_mul(d_model)
                .ok_or(TrainError::InvalidModel(
                    "lexeme hidden weight count overflow",
                ))?;
        let head_dim = lexeme_softmax_head_dim_for_layout(d_model, hidden_dim, head_layout)?;
        let weight_count = vocab_size
            .checked_mul(head_dim)
            .ok_or(TrainError::InvalidModel("lexeme weight count overflow"))?;
        if embeddings.len() != embedding_count {
            return Err(TrainError::InvalidModel("wrong lexeme embedding count"));
        }
        if hidden_weights.len() != hidden_weight_count {
            return Err(TrainError::InvalidModel("wrong lexeme hidden weight count"));
        }
        if output_weights.len() != weight_count {
            return Err(TrainError::InvalidModel("wrong lexeme output weight count"));
        }
        Ok(Self {
            seq_len,
            vocab_size,
            embedding_dim,
            context_features,
            hidden_dim,
            head_layout,
            adapter_logit_shift,
            embeddings,
            hidden_weights,
            output_weights,
        })
    }

    pub fn embedding_hash(&self) -> u64 {
        hash_i16_slice(&self.embeddings)
    }

    pub fn output_weight_hash(&self) -> u64 {
        hash_i8_slice(&self.output_weights)
    }

    pub fn hidden_weight_hash(&self) -> u64 {
        hash_i8_slice(&self.hidden_weights)
    }

    pub fn model_hash(&self) -> u64 {
        let mut hasher = StableHasher::new();
        hasher.update_usize(self.seq_len);
        hasher.update_usize(self.vocab_size);
        hasher.update_usize(self.embedding_dim);
        hasher.update_usize(lexeme_context_features_id(self.context_features));
        hasher.update_usize(self.hidden_dim);
        hasher.update_usize(lexeme_softmax_head_layout_id(self.head_layout));
        hasher.update_usize(usize::from(self.adapter_logit_shift));
        hasher.update_i16_slice(&self.embeddings);
        hasher.update_i8_slice(&self.hidden_weights);
        hasher.update_i8_slice(&self.output_weights);
        hasher.finish()
    }

    fn legacy_v2_model_hash(&self) -> u64 {
        let mut hasher = StableHasher::new();
        hasher.update_usize(self.seq_len);
        hasher.update_usize(self.vocab_size);
        hasher.update_usize(self.embedding_dim);
        hasher.update_i16_slice(&self.embeddings);
        hasher.update_i8_slice(&self.output_weights);
        hasher.finish()
    }

    fn legacy_v4_model_hash(&self) -> u64 {
        let mut hasher = StableHasher::new();
        hasher.update_usize(self.seq_len);
        hasher.update_usize(self.vocab_size);
        hasher.update_usize(self.embedding_dim);
        hasher.update_usize(lexeme_context_features_id(self.context_features));
        hasher.update_usize(self.hidden_dim);
        hasher.update_i16_slice(&self.embeddings);
        hasher.update_i8_slice(&self.hidden_weights);
        hasher.update_i8_slice(&self.output_weights);
        hasher.finish()
    }

    fn legacy_v5_model_hash(&self) -> u64 {
        let mut hasher = StableHasher::new();
        hasher.update_usize(self.seq_len);
        hasher.update_usize(self.vocab_size);
        hasher.update_usize(self.embedding_dim);
        hasher.update_usize(lexeme_context_features_id(self.context_features));
        hasher.update_usize(self.hidden_dim);
        hasher.update_usize(lexeme_softmax_head_layout_id(self.head_layout));
        hasher.update_i16_slice(&self.embeddings);
        hasher.update_i8_slice(&self.hidden_weights);
        hasher.update_i8_slice(&self.output_weights);
        hasher.finish()
    }

    fn legacy_v3_model_hash(&self) -> u64 {
        let mut hasher = StableHasher::new();
        hasher.update_usize(self.seq_len);
        hasher.update_usize(self.vocab_size);
        hasher.update_usize(self.embedding_dim);
        hasher.update_usize(lexeme_context_features_id(self.context_features));
        hasher.update_i16_slice(&self.embeddings);
        hasher.update_i8_slice(&self.output_weights);
        hasher.finish()
    }

    pub fn try_to_bytes(&self) -> Result<Vec<u8>, TrainError> {
        let embedding_bytes =
            checked_i16_tensor_bytes(self.embeddings.len(), "lexeme embedding bytes overflow")?;
        let mut out = Vec::with_capacity(checked_model_capacity(
            96,
            &[
                embedding_bytes,
                self.hidden_weights.len(),
                self.output_weights.len(),
            ],
        )?);
        out.extend_from_slice(LEXEME_SOFTMAX_MODEL_MAGIC);
        out.extend_from_slice(
            &checked_u32(self.seq_len, "lexeme seq_len exceeds u32")?.to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u32(self.vocab_size, "lexeme vocab_size exceeds u32")?.to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u32(self.embedding_dim, "lexeme embedding_dim exceeds u32")?.to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u32(
                lexeme_context_features_id(self.context_features),
                "lexeme context feature id exceeds u32",
            )?
            .to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u32(self.hidden_dim, "lexeme hidden_dim exceeds u32")?.to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u32(
                lexeme_softmax_head_layout_id(self.head_layout),
                "lexeme head layout id exceeds u32",
            )?
            .to_le_bytes(),
        );
        out.extend_from_slice(u32::from(self.adapter_logit_shift).to_le_bytes().as_slice());
        out.extend_from_slice(
            &checked_u64(self.embeddings.len(), "lexeme embedding count exceeds u64")?
                .to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u64(
                self.hidden_weights.len(),
                "lexeme hidden weight count exceeds u64",
            )?
            .to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u64(
                self.output_weights.len(),
                "lexeme output weight count exceeds u64",
            )?
            .to_le_bytes(),
        );
        out.extend_from_slice(&self.embedding_hash().to_le_bytes());
        out.extend_from_slice(&self.hidden_weight_hash().to_le_bytes());
        out.extend_from_slice(&self.output_weight_hash().to_le_bytes());
        out.extend_from_slice(&self.model_hash().to_le_bytes());
        for &embedding in self.embeddings.iter() {
            out.extend_from_slice(&embedding.to_le_bytes());
        }
        out.extend(self.hidden_weights.iter().map(|&weight| weight as u8));
        out.extend(self.output_weights.iter().map(|&weight| weight as u8));
        Ok(out)
    }

    pub fn to_bytes(&self) -> Vec<u8> {
        self.try_to_bytes()
            .expect("lexeme softmax model should fit on-disk format")
    }

    pub fn from_bytes(bytes: &[u8]) -> Result<Self, TrainError> {
        let magic = bytes
            .get(..LEXEME_SOFTMAX_MODEL_MAGIC.len())
            .ok_or(TrainError::InvalidModel("artifact too short"))?;
        let (has_context_features, has_hidden, has_head_layout, has_adapter_logit_shift, legacy_v4) =
            if magic == LEXEME_SOFTMAX_MODEL_MAGIC {
                (true, true, true, true, false)
            } else if magic == LEXEME_SOFTMAX_MODEL_MAGIC_V5 {
                (true, true, true, false, false)
            } else if magic == LEXEME_SOFTMAX_MODEL_MAGIC_V4 {
                (true, true, false, false, true)
            } else if magic == LEXEME_SOFTMAX_MODEL_MAGIC_V3 {
                (true, false, false, false, false)
            } else if magic == LEXEME_SOFTMAX_MODEL_MAGIC_V2 {
                (false, false, false, false, false)
            } else {
                return Err(TrainError::InvalidModel("bad magic"));
            };
        let header_len = LEXEME_SOFTMAX_MODEL_MAGIC.len()
            + 4
            + 4
            + 4
            + if has_context_features { 4 } else { 0 }
            + if has_hidden { 4 } else { 0 }
            + if has_head_layout { 4 } else { 0 }
            + if has_adapter_logit_shift { 4 } else { 0 }
            + 8
            + if has_hidden { 8 } else { 0 }
            + 8
            + 8
            + if has_hidden { 8 } else { 0 }
            + 8
            + 8;
        if bytes.len() < header_len {
            return Err(TrainError::InvalidModel("artifact too short"));
        }

        let mut offset = LEXEME_SOFTMAX_MODEL_MAGIC.len();
        let seq_len = read_u32_le(bytes, &mut offset)? as usize;
        let vocab_size = read_u32_le(bytes, &mut offset)? as usize;
        let embedding_dim = read_u32_le(bytes, &mut offset)? as usize;
        let context_features = if has_context_features {
            lexeme_context_features_from_id(read_u32_le(bytes, &mut offset)?)?
        } else {
            LexemeContextFeatures::Mean
        };
        let hidden_dim = if has_hidden {
            read_u32_le(bytes, &mut offset)? as usize
        } else {
            0
        };
        let head_layout = if has_head_layout {
            lexeme_softmax_head_layout_from_id(read_u32_le(bytes, &mut offset)?)?
        } else if legacy_v4 {
            if hidden_dim == 0 {
                LexemeSoftmaxHeadLayout::Linear
            } else {
                LexemeSoftmaxHeadLayout::HiddenBottleneck
            }
        } else {
            LexemeSoftmaxHeadLayout::Linear
        };
        let adapter_logit_shift = if has_adapter_logit_shift {
            u8::try_from(read_u32_le(bytes, &mut offset)?)
                .map_err(|_| TrainError::InvalidModel("adapter shift exceeds u8"))?
        } else {
            0
        };
        let embedding_count = read_u64_le(bytes, &mut offset)? as usize;
        let hidden_weight_count = if has_hidden {
            read_u64_le(bytes, &mut offset)? as usize
        } else {
            0
        };
        let weight_count = read_u64_le(bytes, &mut offset)? as usize;
        let expected_embedding_hash = read_u64_le(bytes, &mut offset)?;
        let expected_hidden_hash = if has_hidden {
            read_u64_le(bytes, &mut offset)?
        } else {
            hash_i8_slice(&[])
        };
        let expected_weight_hash = read_u64_le(bytes, &mut offset)?;
        let expected_model_hash = read_u64_le(bytes, &mut offset)?;

        let embedding_bytes = embedding_count
            .checked_mul(2)
            .ok_or(TrainError::InvalidModel("embedding length overflow"))?;
        let embedding_end = offset
            .checked_add(embedding_bytes)
            .ok_or(TrainError::InvalidModel("embedding offset overflow"))?;
        let hidden_weight_end = embedding_end
            .checked_add(hidden_weight_count)
            .ok_or(TrainError::InvalidModel("hidden weight offset overflow"))?;
        let weight_end = hidden_weight_end
            .checked_add(weight_count)
            .ok_or(TrainError::InvalidModel("weight offset overflow"))?;
        if bytes.len() != weight_end {
            return Err(TrainError::InvalidModel("artifact length mismatch"));
        }

        let mut embeddings = Vec::with_capacity(embedding_count);
        for chunk in bytes[offset..embedding_end].chunks_exact(2) {
            embeddings.push(i16::from_le_bytes(
                chunk
                    .try_into()
                    .map_err(|_| TrainError::InvalidModel("bad embedding"))?,
            ));
        }
        let hidden_weights = bytes[embedding_end..hidden_weight_end]
            .iter()
            .map(|&byte| byte as i8)
            .collect::<Vec<_>>();
        let output_weights = bytes[hidden_weight_end..weight_end]
            .iter()
            .map(|&byte| byte as i8)
            .collect::<Vec<_>>();
        let model = Self::new_with_context_features_hidden_layout_and_adapter_shift(
            seq_len,
            vocab_size,
            embedding_dim,
            context_features,
            hidden_dim,
            head_layout,
            adapter_logit_shift,
            embeddings,
            hidden_weights,
            output_weights,
        )?;
        if model.embedding_hash() != expected_embedding_hash {
            return Err(TrainError::InvalidModel("embedding hash mismatch"));
        }
        if model.hidden_weight_hash() != expected_hidden_hash {
            return Err(TrainError::InvalidModel("hidden weight hash mismatch"));
        }
        if model.output_weight_hash() != expected_weight_hash {
            return Err(TrainError::InvalidModel("weight hash mismatch"));
        }
        let actual_model_hash = if has_adapter_logit_shift {
            model.model_hash()
        } else if has_head_layout {
            model.legacy_v5_model_hash()
        } else if legacy_v4 {
            model.legacy_v4_model_hash()
        } else if has_context_features {
            model.legacy_v3_model_hash()
        } else {
            model.legacy_v2_model_hash()
        };
        if actual_model_hash != expected_model_hash {
            return Err(TrainError::InvalidModel("model hash mismatch"));
        }
        Ok(model)
    }
}

pub fn reduce_lexeme_softmax_models(
    models: Vec<LexemeSoftmaxModel>,
) -> Result<(LexemeSoftmaxModel, LexemeSoftmaxReductionTrace), TrainError> {
    let first = models.first().ok_or(TrainError::InvalidConfig)?;
    for model in models.iter().skip(1) {
        validate_lexeme_softmax_reduce_shape(first, model)?;
    }

    let embeddings =
        average_lexeme_reduce_i16_tensors(models.iter().map(|model| model.embeddings.as_slice()))?;
    let hidden_weights = average_lexeme_reduce_i8_tensors(
        models.iter().map(|model| model.hidden_weights.as_slice()),
    )?;
    let output_weights = average_lexeme_reduce_i8_tensors(
        models.iter().map(|model| model.output_weights.as_slice()),
    )?;

    let reduced = LexemeSoftmaxModel::new_with_context_features_hidden_layout_and_adapter_shift(
        first.seq_len,
        first.vocab_size,
        first.embedding_dim,
        first.context_features,
        first.hidden_dim,
        first.head_layout,
        first.adapter_logit_shift,
        embeddings,
        hidden_weights,
        output_weights,
    )?;
    let artifact_bytes = reduced.try_to_bytes()?.len();
    let parameter_bytes = checked_i16_tensor_bytes(
        reduced.embeddings.len(),
        "lexeme reduce embedding bytes overflow",
    )?
    .checked_add(reduced.hidden_weights.len())
    .and_then(|value| value.checked_add(reduced.output_weights.len()))
    .ok_or(TrainError::InvalidModel(
        "lexeme reduce parameter bytes overflow",
    ))?;
    let trace = LexemeSoftmaxReductionTrace {
        reducer: "equal_weight_integer_average_v1",
        model_count: models.len(),
        seq_len: reduced.seq_len,
        vocab_size: reduced.vocab_size,
        embedding_dim: reduced.embedding_dim,
        context_features: reduced.context_features,
        hidden_dim: reduced.hidden_dim,
        head_layout: reduced.head_layout,
        adapter_logit_shift: reduced.adapter_logit_shift,
        parameter_bytes,
        artifact_bytes,
        input_model_hashes: models.iter().map(LexemeSoftmaxModel::model_hash).collect(),
        input_embedding_hashes: models
            .iter()
            .map(LexemeSoftmaxModel::embedding_hash)
            .collect(),
        input_hidden_weight_hashes: models
            .iter()
            .map(LexemeSoftmaxModel::hidden_weight_hash)
            .collect(),
        input_output_weight_hashes: models
            .iter()
            .map(LexemeSoftmaxModel::output_weight_hash)
            .collect(),
        output_model_hash: reduced.model_hash(),
        output_embedding_hash: reduced.embedding_hash(),
        output_hidden_weight_hash: reduced.hidden_weight_hash(),
        output_weight_hash: reduced.output_weight_hash(),
    };
    Ok((reduced, trace))
}

fn validate_lexeme_softmax_reduce_shape(
    expected: &LexemeSoftmaxModel,
    candidate: &LexemeSoftmaxModel,
) -> Result<(), TrainError> {
    if expected.seq_len != candidate.seq_len
        || expected.vocab_size != candidate.vocab_size
        || expected.embedding_dim != candidate.embedding_dim
        || expected.context_features != candidate.context_features
        || expected.hidden_dim != candidate.hidden_dim
        || expected.head_layout != candidate.head_layout
        || expected.adapter_logit_shift != candidate.adapter_logit_shift
        || expected.embeddings.len() != candidate.embeddings.len()
        || expected.hidden_weights.len() != candidate.hidden_weights.len()
        || expected.output_weights.len() != candidate.output_weights.len()
    {
        return Err(TrainError::InvalidModel(
            "incompatible lexeme softmax models for reduction",
        ));
    }
    Ok(())
}

fn average_lexeme_reduce_i16_tensors<'a, I>(slices: I) -> Result<Vec<i16>, TrainError>
where
    I: IntoIterator<Item = &'a [i16]>,
{
    let mut count = 0_usize;
    let mut sums = Vec::<i64>::new();
    for slice in slices {
        if count == 0 {
            sums.resize(slice.len(), 0);
        } else if slice.len() != sums.len() {
            return Err(TrainError::InvalidModel(
                "incompatible lexeme i16 tensor length for reduction",
            ));
        }
        for (sum, &value) in sums.iter_mut().zip(slice.iter()) {
            *sum = sum
                .checked_add(i64::from(value))
                .ok_or(TrainError::CoreRejected("lexeme_reduce_i16_accumulate"))?;
        }
        count = count
            .checked_add(1)
            .ok_or(TrainError::CoreRejected("lexeme_reduce_i16_count"))?;
    }
    if count == 0 {
        return Err(TrainError::InvalidConfig);
    }

    sums.into_iter()
        .map(|sum| round_div_i64(sum, count).map(saturate_i16))
        .collect()
}

fn average_lexeme_reduce_i8_tensors<'a, I>(slices: I) -> Result<Vec<i8>, TrainError>
where
    I: IntoIterator<Item = &'a [i8]>,
{
    let mut count = 0_usize;
    let mut sums = Vec::<i64>::new();
    for slice in slices {
        if count == 0 {
            sums.resize(slice.len(), 0);
        } else if slice.len() != sums.len() {
            return Err(TrainError::InvalidModel(
                "incompatible lexeme i8 tensor length for reduction",
            ));
        }
        for (sum, &value) in sums.iter_mut().zip(slice.iter()) {
            *sum = sum
                .checked_add(i64::from(value))
                .ok_or(TrainError::CoreRejected("lexeme_reduce_i8_accumulate"))?;
        }
        count = count
            .checked_add(1)
            .ok_or(TrainError::CoreRejected("lexeme_reduce_i8_count"))?;
    }
    if count == 0 {
        return Err(TrainError::InvalidConfig);
    }

    sums.into_iter()
        .map(|sum| round_div_i64(sum, count).map(saturate_i8))
        .collect()
}

impl MiniTransformerMlpModel {
    pub fn new_initial() -> Self {
        Self::new_initial_with_seq_len(DEFAULT_MINI_TRANSFORMER_SEQ_LEN)
    }

    pub fn new_initial_with_seq_len(context_seq_len: usize) -> Self {
        Self {
            context_seq_len,
            embeddings: initial_mini_transformer_embeddings(),
            position_embeddings: initial_mini_transformer_position_embeddings(context_seq_len),
            q_weights: identity_i8_matrix(MINI_TRANSFORMER_D_MODEL),
            k_weights: identity_i8_matrix(MINI_TRANSFORMER_D_MODEL),
            v_weights: identity_i8_matrix(MINI_TRANSFORMER_D_MODEL),
            o_weights: identity_i8_matrix(MINI_TRANSFORMER_D_MODEL),
            up_weights: initial_mini_transformer_mlp_up_or_gate_weights(),
            gate_weights: initial_mini_transformer_mlp_up_or_gate_weights(),
            down_weights: initial_mini_transformer_mlp_down_weights(),
            output_weights: initial_mini_transformer_output_weights(),
        }
    }

    #[allow(clippy::too_many_arguments)]
    pub fn new(
        context_seq_len: usize,
        embeddings: Vec<i16>,
        position_embeddings: Vec<i16>,
        q_weights: Vec<i8>,
        k_weights: Vec<i8>,
        v_weights: Vec<i8>,
        o_weights: Vec<i8>,
        up_weights: Vec<i8>,
        gate_weights: Vec<i8>,
        down_weights: Vec<i8>,
        output_weights: Vec<i8>,
    ) -> Result<Self, TrainError> {
        if context_seq_len == 0 {
            return Err(TrainError::InvalidModel(
                "bad mini transformer context seq_len",
            ));
        }
        if embeddings.len() != BYTE_VOCAB * MINI_TRANSFORMER_D_MODEL {
            return Err(TrainError::InvalidModel(
                "wrong mini transformer embedding count",
            ));
        }
        if position_embeddings.len()
            != context_seq_len
                .checked_mul(MINI_TRANSFORMER_D_MODEL)
                .ok_or(TrainError::InvalidModel(
                    "mini transformer position count overflow",
                ))?
        {
            return Err(TrainError::InvalidModel(
                "wrong mini transformer position embedding count",
            ));
        }
        let attention_weight_count = MINI_TRANSFORMER_D_MODEL * MINI_TRANSFORMER_D_MODEL;
        if q_weights.len() != attention_weight_count
            || k_weights.len() != attention_weight_count
            || v_weights.len() != attention_weight_count
            || o_weights.len() != attention_weight_count
        {
            return Err(TrainError::InvalidModel(
                "wrong mini transformer attention weight count",
            ));
        }
        let up_or_gate_count = MINI_TRANSFORMER_D_MODEL * MINI_TRANSFORMER_HIDDEN_DIM;
        if up_weights.len() != up_or_gate_count || gate_weights.len() != up_or_gate_count {
            return Err(TrainError::InvalidModel(
                "wrong mini transformer up/gate weight count",
            ));
        }
        if down_weights.len() != MINI_TRANSFORMER_HIDDEN_DIM * MINI_TRANSFORMER_D_MODEL {
            return Err(TrainError::InvalidModel(
                "wrong mini transformer down weight count",
            ));
        }
        if output_weights.len() != BYTE_VOCAB * MINI_TRANSFORMER_D_MODEL {
            return Err(TrainError::InvalidModel(
                "wrong mini transformer output weight count",
            ));
        }

        Ok(Self {
            context_seq_len,
            embeddings,
            position_embeddings,
            q_weights,
            k_weights,
            v_weights,
            o_weights,
            up_weights,
            gate_weights,
            down_weights,
            output_weights,
        })
    }

    pub fn embedding_hash(&self) -> u64 {
        let mut hasher = StableHasher::new();
        hasher.update_i16_slice(&self.embeddings);
        hasher.update_i16_slice(&self.position_embeddings);
        hasher.finish()
    }

    pub fn attention_hash(&self) -> u64 {
        let mut hasher = StableHasher::new();
        hasher.update_i8_slice(&self.q_weights);
        hasher.update_i8_slice(&self.k_weights);
        hasher.update_i8_slice(&self.v_weights);
        hasher.update_i8_slice(&self.o_weights);
        hasher.finish()
    }

    pub fn attention_q_hash(&self) -> u64 {
        hash_i8_slice(&self.q_weights)
    }

    pub fn attention_k_hash(&self) -> u64 {
        hash_i8_slice(&self.k_weights)
    }

    pub fn attention_v_hash(&self) -> u64 {
        hash_i8_slice(&self.v_weights)
    }

    pub fn attention_o_hash(&self) -> u64 {
        hash_i8_slice(&self.o_weights)
    }

    pub fn mlp_hash(&self) -> u64 {
        hash_three_i8_slices(&self.up_weights, &self.gate_weights, &self.down_weights)
    }

    pub fn output_head_hash(&self) -> u64 {
        hash_i8_slice(&self.output_weights)
    }

    pub fn model_hash(&self) -> u64 {
        let mut hasher = StableHasher::new();
        hasher.update_usize(self.context_seq_len);
        hasher.update_i16_slice(&self.embeddings);
        hasher.update_i16_slice(&self.position_embeddings);
        hasher.update_i8_slice(&self.q_weights);
        hasher.update_i8_slice(&self.k_weights);
        hasher.update_i8_slice(&self.v_weights);
        hasher.update_i8_slice(&self.o_weights);
        hasher.update_i8_slice(&self.up_weights);
        hasher.update_i8_slice(&self.gate_weights);
        hasher.update_i8_slice(&self.down_weights);
        hasher.update_i8_slice(&self.output_weights);
        hasher.finish()
    }

    pub fn try_to_bytes(&self) -> Result<Vec<u8>, TrainError> {
        let embedding_bytes = checked_i16_tensor_bytes(
            self.embeddings.len(),
            "mini transformer embedding bytes overflow",
        )?;
        let position_embedding_bytes = checked_i16_tensor_bytes(
            self.position_embeddings.len(),
            "mini transformer position embedding bytes overflow",
        )?;
        let weight_bytes = checked_model_capacity(
            0,
            &[
                self.q_weights.len(),
                self.k_weights.len(),
                self.v_weights.len(),
                self.o_weights.len(),
                self.up_weights.len(),
                self.gate_weights.len(),
                self.down_weights.len(),
                self.output_weights.len(),
            ],
        )?;
        let mut out = Vec::with_capacity(checked_model_capacity(
            136,
            &[embedding_bytes, position_embedding_bytes, weight_bytes],
        )?);
        out.extend_from_slice(MINI_TRANSFORMER_MODEL_MAGIC);
        out.extend_from_slice(&checked_u32(BYTE_VOCAB, "byte vocab exceeds u32")?.to_le_bytes());
        out.extend_from_slice(
            &checked_u32(
                MINI_TRANSFORMER_D_MODEL,
                "mini transformer d_model exceeds u32",
            )?
            .to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u32(MINI_TRANSFORMER_HEADS, "mini transformer heads exceeds u32")?
                .to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u32(
                MINI_TRANSFORMER_HIDDEN_DIM,
                "mini transformer hidden_dim exceeds u32",
            )?
            .to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u32(
                self.context_seq_len,
                "mini transformer context_seq_len exceeds u32",
            )?
            .to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u64(
                self.embeddings.len(),
                "mini transformer embedding count exceeds u64",
            )?
            .to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u64(
                self.position_embeddings.len(),
                "mini transformer position embedding count exceeds u64",
            )?
            .to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u64(self.q_weights.len(), "mini transformer q count exceeds u64")?
                .to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u64(self.k_weights.len(), "mini transformer k count exceeds u64")?
                .to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u64(self.v_weights.len(), "mini transformer v count exceeds u64")?
                .to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u64(self.o_weights.len(), "mini transformer o count exceeds u64")?
                .to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u64(
                self.up_weights.len(),
                "mini transformer up count exceeds u64",
            )?
            .to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u64(
                self.gate_weights.len(),
                "mini transformer gate count exceeds u64",
            )?
            .to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u64(
                self.down_weights.len(),
                "mini transformer down count exceeds u64",
            )?
            .to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u64(
                self.output_weights.len(),
                "mini transformer output count exceeds u64",
            )?
            .to_le_bytes(),
        );
        out.extend_from_slice(&self.embedding_hash().to_le_bytes());
        out.extend_from_slice(&self.attention_q_hash().to_le_bytes());
        out.extend_from_slice(&self.attention_k_hash().to_le_bytes());
        out.extend_from_slice(&self.attention_v_hash().to_le_bytes());
        out.extend_from_slice(&self.attention_o_hash().to_le_bytes());
        out.extend_from_slice(&self.mlp_hash().to_le_bytes());
        out.extend_from_slice(&self.output_head_hash().to_le_bytes());
        out.extend_from_slice(&self.model_hash().to_le_bytes());
        for &embedding in self.embeddings.iter() {
            out.extend_from_slice(&embedding.to_le_bytes());
        }
        for &embedding in self.position_embeddings.iter() {
            out.extend_from_slice(&embedding.to_le_bytes());
        }
        out.extend(self.q_weights.iter().map(|&weight| weight as u8));
        out.extend(self.k_weights.iter().map(|&weight| weight as u8));
        out.extend(self.v_weights.iter().map(|&weight| weight as u8));
        out.extend(self.o_weights.iter().map(|&weight| weight as u8));
        out.extend(self.up_weights.iter().map(|&weight| weight as u8));
        out.extend(self.gate_weights.iter().map(|&weight| weight as u8));
        out.extend(self.down_weights.iter().map(|&weight| weight as u8));
        out.extend(self.output_weights.iter().map(|&weight| weight as u8));
        Ok(out)
    }

    pub fn to_bytes(&self) -> Vec<u8> {
        self.try_to_bytes()
            .expect("mini transformer model should fit on-disk format")
    }

    pub fn from_bytes(bytes: &[u8]) -> Result<Self, TrainError> {
        let header_len = MINI_TRANSFORMER_MODEL_MAGIC.len() + 4 * 5 + 8 * 10 + 8 * 8;
        if bytes.len() < header_len {
            return Err(TrainError::InvalidModel("artifact too short"));
        }
        if &bytes[..MINI_TRANSFORMER_MODEL_MAGIC.len()] != MINI_TRANSFORMER_MODEL_MAGIC {
            return Err(TrainError::InvalidModel("bad magic"));
        }

        let mut offset = MINI_TRANSFORMER_MODEL_MAGIC.len();
        let vocab = read_u32_le(bytes, &mut offset)? as usize;
        let d_model = read_u32_le(bytes, &mut offset)? as usize;
        let heads = read_u32_le(bytes, &mut offset)? as usize;
        let hidden_dim = read_u32_le(bytes, &mut offset)? as usize;
        let context_seq_len = read_u32_le(bytes, &mut offset)? as usize;
        let embedding_count = read_u64_le(bytes, &mut offset)? as usize;
        let position_embedding_count = read_u64_le(bytes, &mut offset)? as usize;
        let q_count = read_u64_le(bytes, &mut offset)? as usize;
        let k_count = read_u64_le(bytes, &mut offset)? as usize;
        let v_count = read_u64_le(bytes, &mut offset)? as usize;
        let o_count = read_u64_le(bytes, &mut offset)? as usize;
        let up_count = read_u64_le(bytes, &mut offset)? as usize;
        let gate_count = read_u64_le(bytes, &mut offset)? as usize;
        let down_count = read_u64_le(bytes, &mut offset)? as usize;
        let output_count = read_u64_le(bytes, &mut offset)? as usize;
        let expected_embedding_hash = read_u64_le(bytes, &mut offset)?;
        let expected_q_hash = read_u64_le(bytes, &mut offset)?;
        let expected_k_hash = read_u64_le(bytes, &mut offset)?;
        let expected_v_hash = read_u64_le(bytes, &mut offset)?;
        let expected_o_hash = read_u64_le(bytes, &mut offset)?;
        let expected_mlp_hash = read_u64_le(bytes, &mut offset)?;
        let expected_output_hash = read_u64_le(bytes, &mut offset)?;
        let expected_model_hash = read_u64_le(bytes, &mut offset)?;

        if vocab != BYTE_VOCAB
            || d_model != MINI_TRANSFORMER_D_MODEL
            || heads != MINI_TRANSFORMER_HEADS
            || hidden_dim != MINI_TRANSFORMER_HIDDEN_DIM
            || context_seq_len == 0
        {
            return Err(TrainError::InvalidModel("shape mismatch"));
        }

        let expected_attention_count = MINI_TRANSFORMER_D_MODEL * MINI_TRANSFORMER_D_MODEL;
        let expected_position_embedding_count = context_seq_len
            .checked_mul(MINI_TRANSFORMER_D_MODEL)
            .ok_or(TrainError::InvalidModel(
                "position embedding count overflow",
            ))?;
        if embedding_count != BYTE_VOCAB * MINI_TRANSFORMER_D_MODEL
            || position_embedding_count != expected_position_embedding_count
            || q_count != expected_attention_count
            || k_count != expected_attention_count
            || v_count != expected_attention_count
            || o_count != expected_attention_count
            || up_count != MINI_TRANSFORMER_D_MODEL * MINI_TRANSFORMER_HIDDEN_DIM
            || gate_count != MINI_TRANSFORMER_D_MODEL * MINI_TRANSFORMER_HIDDEN_DIM
            || down_count != MINI_TRANSFORMER_HIDDEN_DIM * MINI_TRANSFORMER_D_MODEL
            || output_count != BYTE_VOCAB * MINI_TRANSFORMER_D_MODEL
        {
            return Err(TrainError::InvalidModel("tensor count mismatch"));
        }

        let embedding_bytes = embedding_count
            .checked_mul(2)
            .ok_or(TrainError::InvalidModel("embedding length overflow"))?;
        let position_embedding_bytes =
            position_embedding_count
                .checked_mul(2)
                .ok_or(TrainError::InvalidModel(
                    "position embedding length overflow",
                ))?;
        let weight_bytes = q_count
            .checked_add(k_count)
            .and_then(|value| value.checked_add(v_count))
            .and_then(|value| value.checked_add(o_count))
            .and_then(|value| value.checked_add(up_count))
            .and_then(|value| value.checked_add(gate_count))
            .and_then(|value| value.checked_add(down_count))
            .and_then(|value| value.checked_add(output_count))
            .ok_or(TrainError::InvalidModel("weight length overflow"))?;
        let expected_len = offset
            .checked_add(embedding_bytes)
            .and_then(|value| value.checked_add(position_embedding_bytes))
            .and_then(|value| value.checked_add(weight_bytes))
            .ok_or(TrainError::InvalidModel("artifact length overflow"))?;
        if bytes.len() != expected_len {
            return Err(TrainError::InvalidModel("artifact length mismatch"));
        }

        let embedding_end = offset + embedding_bytes;
        let mut embeddings = Vec::with_capacity(embedding_count);
        for chunk in bytes[offset..embedding_end].chunks_exact(2) {
            embeddings.push(i16::from_le_bytes(
                chunk
                    .try_into()
                    .map_err(|_| TrainError::InvalidModel("bad embedding"))?,
            ));
        }
        offset = embedding_end;

        let position_embedding_end = offset + position_embedding_bytes;
        let mut position_embeddings = Vec::with_capacity(position_embedding_count);
        for chunk in bytes[offset..position_embedding_end].chunks_exact(2) {
            position_embeddings.push(i16::from_le_bytes(
                chunk
                    .try_into()
                    .map_err(|_| TrainError::InvalidModel("bad position embedding"))?,
            ));
        }
        offset = position_embedding_end;

        let q_weights = read_i8_vec(bytes, &mut offset, q_count)?;
        let k_weights = read_i8_vec(bytes, &mut offset, k_count)?;
        let v_weights = read_i8_vec(bytes, &mut offset, v_count)?;
        let o_weights = read_i8_vec(bytes, &mut offset, o_count)?;
        let up_weights = read_i8_vec(bytes, &mut offset, up_count)?;
        let gate_weights = read_i8_vec(bytes, &mut offset, gate_count)?;
        let down_weights = read_i8_vec(bytes, &mut offset, down_count)?;
        let output_weights = read_i8_vec(bytes, &mut offset, output_count)?;

        let model = Self::new(
            context_seq_len,
            embeddings,
            position_embeddings,
            q_weights,
            k_weights,
            v_weights,
            o_weights,
            up_weights,
            gate_weights,
            down_weights,
            output_weights,
        )?;
        if model.embedding_hash() != expected_embedding_hash {
            return Err(TrainError::InvalidModel("embedding hash mismatch"));
        }
        if model.attention_q_hash() != expected_q_hash
            || model.attention_k_hash() != expected_k_hash
            || model.attention_v_hash() != expected_v_hash
            || model.attention_o_hash() != expected_o_hash
        {
            return Err(TrainError::InvalidModel("attention hash mismatch"));
        }
        if model.mlp_hash() != expected_mlp_hash {
            return Err(TrainError::InvalidModel("mlp hash mismatch"));
        }
        if model.output_head_hash() != expected_output_hash {
            return Err(TrainError::InvalidModel("output hash mismatch"));
        }
        if model.model_hash() != expected_model_hash {
            return Err(TrainError::InvalidModel("model hash mismatch"));
        }
        Ok(model)
    }
}

impl MiniTransformerMlpSwarmWorkerArtifact {
    pub fn try_to_bytes(&self) -> Result<Vec<u8>, TrainError> {
        if self.worker_count == 0
            || self.worker.worker_index >= self.worker_count
            || self.model.model_hash() != self.worker.final_model_hash
        {
            return Err(TrainError::InvalidModel("bad swarm worker artifact"));
        }
        let model_bytes = self.model.try_to_bytes()?;
        let mut out = Vec::with_capacity(checked_model_capacity(224, &[model_bytes.len()])?);
        out.extend_from_slice(MINI_TRANSFORMER_SWARM_WORKER_ARTIFACT_MAGIC);
        push_model_usize(&mut out, self.worker_count, "worker count exceeds u64")?;
        push_model_usize(&mut out, self.token_count, "token count exceeds u64")?;
        out.extend_from_slice(&self.token_hash.to_le_bytes());
        push_model_usize(
            &mut out,
            self.base_window_offset,
            "base window offset exceeds u64",
        )?;
        push_model_usize(&mut out, self.base_stride, "base stride exceeds u64")?;
        push_model_optional_usize(
            &mut out,
            self.base_max_windows,
            "base max windows exceeds u64",
        )?;
        out.extend_from_slice(&self.base_model_hash.to_le_bytes());
        push_model_usize(
            &mut out,
            self.worker.worker_index,
            "worker index exceeds u64",
        )?;
        push_model_usize(
            &mut out,
            self.worker.window_offset,
            "worker window offset exceeds u64",
        )?;
        push_model_usize(&mut out, self.worker.stride, "worker stride exceeds u64")?;
        push_model_optional_usize(
            &mut out,
            self.worker.max_windows,
            "worker max windows exceeds u64",
        )?;
        out.extend_from_slice(&self.worker.window_hash.to_le_bytes());
        push_model_usize(&mut out, self.worker.windows, "worker windows exceeds u64")?;
        push_model_usize(
            &mut out,
            self.worker.examined_windows,
            "worker examined windows exceeds u64",
        )?;
        push_model_usize(&mut out, self.worker.updates, "worker updates exceeds u64")?;
        push_model_usize(
            &mut out,
            self.worker.accepted_batch_count,
            "worker accepted batches exceeds u64",
        )?;
        push_model_usize(
            &mut out,
            self.worker.rejected_batch_count,
            "worker rejected batches exceeds u64",
        )?;
        push_model_usize(
            &mut out,
            self.worker.rollback_count,
            "worker rollbacks exceeds u64",
        )?;
        push_model_usize(
            &mut out,
            self.worker.rejected_window_count,
            "worker rejected windows exceeds u64",
        )?;
        push_model_usize(
            &mut out,
            self.worker.final_invalid_forward_count,
            "worker invalid forward count exceeds u64",
        )?;
        push_model_usize(
            &mut out,
            self.worker.initial_total_error,
            "worker initial total error exceeds u64",
        )?;
        push_model_usize(
            &mut out,
            self.worker.final_total_error,
            "worker final total error exceeds u64",
        )?;
        push_model_usize(
            &mut out,
            self.worker.initial_probability_error_q15,
            "worker initial probability error exceeds u64",
        )?;
        push_model_usize(
            &mut out,
            self.worker.final_probability_error_q15,
            "worker final probability error exceeds u64",
        )?;
        push_model_usize(
            &mut out,
            self.worker.final_accuracy_per_mille,
            "worker final accuracy exceeds u64",
        )?;
        out.extend_from_slice(&self.worker.final_model_hash.to_le_bytes());
        out.extend_from_slice(&self.worker.final_logits_hash.to_le_bytes());
        push_model_usize(
            &mut out,
            model_bytes.len(),
            "worker model bytes exceeds u64",
        )?;
        out.extend_from_slice(&model_bytes);
        Ok(out)
    }

    pub fn to_bytes(&self) -> Vec<u8> {
        self.try_to_bytes()
            .expect("mini transformer swarm worker artifact should fit on-disk format")
    }

    pub fn from_bytes(bytes: &[u8]) -> Result<Self, TrainError> {
        if bytes.len() < MINI_TRANSFORMER_SWARM_WORKER_ARTIFACT_MAGIC.len() {
            return Err(TrainError::InvalidModel("swarm worker artifact too short"));
        }
        if &bytes[..MINI_TRANSFORMER_SWARM_WORKER_ARTIFACT_MAGIC.len()]
            != MINI_TRANSFORMER_SWARM_WORKER_ARTIFACT_MAGIC
        {
            return Err(TrainError::InvalidModel("bad swarm worker magic"));
        }

        let mut offset = MINI_TRANSFORMER_SWARM_WORKER_ARTIFACT_MAGIC.len();
        let worker_count = read_model_usize(bytes, &mut offset)?;
        let token_count = read_model_usize(bytes, &mut offset)?;
        let token_hash = read_u64_le(bytes, &mut offset)?;
        let base_window_offset = read_model_usize(bytes, &mut offset)?;
        let base_stride = read_model_usize(bytes, &mut offset)?;
        let base_max_windows = read_model_optional_usize(bytes, &mut offset)?;
        let base_model_hash = read_u64_le(bytes, &mut offset)?;
        let worker_index = read_model_usize(bytes, &mut offset)?;
        let window_offset = read_model_usize(bytes, &mut offset)?;
        let stride = read_model_usize(bytes, &mut offset)?;
        let max_windows = read_model_optional_usize(bytes, &mut offset)?;
        let window_hash = read_u64_le(bytes, &mut offset)?;
        let windows = read_model_usize(bytes, &mut offset)?;
        let examined_windows = read_model_usize(bytes, &mut offset)?;
        let updates = read_model_usize(bytes, &mut offset)?;
        let accepted_batch_count = read_model_usize(bytes, &mut offset)?;
        let rejected_batch_count = read_model_usize(bytes, &mut offset)?;
        let rollback_count = read_model_usize(bytes, &mut offset)?;
        let rejected_window_count = read_model_usize(bytes, &mut offset)?;
        let final_invalid_forward_count = read_model_usize(bytes, &mut offset)?;
        let initial_total_error = read_model_usize(bytes, &mut offset)?;
        let final_total_error = read_model_usize(bytes, &mut offset)?;
        let initial_probability_error_q15 = read_model_usize(bytes, &mut offset)?;
        let final_probability_error_q15 = read_model_usize(bytes, &mut offset)?;
        let final_accuracy_per_mille = read_model_usize(bytes, &mut offset)?;
        let final_model_hash = read_u64_le(bytes, &mut offset)?;
        let final_logits_hash = read_u64_le(bytes, &mut offset)?;
        let model_len = read_model_usize(bytes, &mut offset)?;
        let model_end = offset
            .checked_add(model_len)
            .ok_or(TrainError::InvalidModel(
                "swarm worker model offset overflow",
            ))?;
        let model_bytes = bytes
            .get(offset..model_end)
            .ok_or(TrainError::InvalidModel("swarm worker model truncated"))?;
        offset = model_end;
        if offset != bytes.len() || worker_count == 0 || worker_index >= worker_count {
            return Err(TrainError::InvalidModel("bad swarm worker header"));
        }

        let model = MiniTransformerMlpModel::from_bytes(model_bytes)?;
        if model.model_hash() != final_model_hash {
            return Err(TrainError::InvalidModel("swarm worker model hash mismatch"));
        }
        Ok(Self {
            worker_count,
            token_count,
            token_hash,
            base_window_offset,
            base_stride,
            base_max_windows,
            base_model_hash,
            worker: MiniTransformerMlpSwarmWorkerTrace {
                worker_index,
                window_offset,
                stride,
                max_windows,
                token_hash,
                window_hash,
                windows,
                examined_windows,
                updates,
                accepted_batch_count,
                rejected_batch_count,
                rollback_count,
                rejected_window_count,
                final_invalid_forward_count,
                initial_total_error,
                final_total_error,
                initial_probability_error_q15,
                final_probability_error_q15,
                final_accuracy_per_mille,
                final_model_hash,
                final_logits_hash,
            },
            model,
        })
    }

    pub fn to_json_line(&self) -> String {
        let mut out = String::new();
        out.push('{');
        push_string_field(&mut out, "schema", MINI_TRANSFORMER_SWARM_WORKER_SCHEMA);
        comma(&mut out);
        push_string_field(&mut out, "authority", AUTHORITY);
        comma(&mut out);
        push_string_field(
            &mut out,
            "task",
            "wiki_bard_mini_transformer_mlp_swarm_worker",
        );
        comma(&mut out);
        out.push_str("\"data\":{");
        push_usize_field(&mut out, "token_count", self.token_count);
        comma(&mut out);
        push_hash_field(&mut out, "token_hash", self.token_hash);
        out.push('}');
        comma(&mut out);
        out.push_str("\"swarm\":{");
        push_usize_field(&mut out, "worker_count", self.worker_count);
        comma(&mut out);
        push_usize_field(&mut out, "base_window_offset", self.base_window_offset);
        comma(&mut out);
        push_usize_field(&mut out, "base_stride", self.base_stride);
        comma(&mut out);
        push_optional_usize_field(&mut out, "base_max_windows", self.base_max_windows);
        comma(&mut out);
        push_hash_field(&mut out, "base_model_hash", self.base_model_hash);
        out.push('}');
        comma(&mut out);
        push_quoted(&mut out, "worker");
        out.push(':');
        push_mini_transformer_swarm_worker(&mut out, &self.worker);
        comma(&mut out);
        out.push_str("\"artifact\":{");
        push_string_field(&mut out, "format", "nsrlswarm-worker");
        comma(&mut out);
        push_string_field(&mut out, "magic", "NSRLWK1");
        comma(&mut out);
        push_usize_field(
            &mut out,
            "model_bytes",
            self.model
                .try_to_bytes()
                .map(|bytes| bytes.len())
                .unwrap_or(0),
        );
        out.push('}');
        out.push('}');
        out.push('\n');
        out
    }
}

impl MiniTransformerMlpSwarmModel {
    pub fn new(
        best_worker_index: usize,
        workers: Vec<MiniTransformerMlpModel>,
    ) -> Result<Self, TrainError> {
        let first = workers
            .first()
            .ok_or(TrainError::InvalidModel("empty mini transformer swarm"))?;
        if best_worker_index >= workers.len() {
            return Err(TrainError::InvalidModel("swarm best worker out of range"));
        }
        let context_seq_len = first.context_seq_len;
        if context_seq_len == 0
            || workers
                .iter()
                .any(|worker| worker.context_seq_len != context_seq_len)
        {
            return Err(TrainError::InvalidModel(
                "swarm worker context length mismatch",
            ));
        }
        Ok(Self {
            context_seq_len,
            best_worker_index,
            workers,
        })
    }

    pub fn worker_count(&self) -> usize {
        self.workers.len()
    }

    pub fn model_hash(&self) -> u64 {
        let mut hasher = StableHasher::new();
        hasher.update_usize(self.context_seq_len);
        hasher.update_usize(self.best_worker_index);
        hasher.update_usize(self.workers.len());
        for worker in &self.workers {
            hasher.update_bytes(&worker.model_hash().to_le_bytes());
        }
        hasher.finish()
    }

    pub fn embedding_hash(&self) -> u64 {
        let mut hasher = StableHasher::new();
        hasher.update_usize(self.workers.len());
        for worker in &self.workers {
            hasher.update_bytes(&worker.embedding_hash().to_le_bytes());
        }
        hasher.finish()
    }

    pub fn attention_hash(&self) -> u64 {
        let mut hasher = StableHasher::new();
        hasher.update_usize(self.workers.len());
        for worker in &self.workers {
            hasher.update_bytes(&worker.attention_hash().to_le_bytes());
        }
        hasher.finish()
    }

    pub fn mlp_hash(&self) -> u64 {
        let mut hasher = StableHasher::new();
        hasher.update_usize(self.workers.len());
        for worker in &self.workers {
            hasher.update_bytes(&worker.mlp_hash().to_le_bytes());
        }
        hasher.finish()
    }

    pub fn output_head_hash(&self) -> u64 {
        let mut hasher = StableHasher::new();
        hasher.update_usize(self.workers.len());
        for worker in &self.workers {
            hasher.update_bytes(&worker.output_head_hash().to_le_bytes());
        }
        hasher.finish()
    }

    pub fn try_to_bytes(&self) -> Result<Vec<u8>, TrainError> {
        let worker_blobs = self
            .workers
            .iter()
            .map(MiniTransformerMlpModel::try_to_bytes)
            .collect::<Result<Vec<_>, _>>()?;
        let payload_bytes = worker_blobs.iter().try_fold(0_usize, |total, blob| {
            total
                .checked_add(8)
                .and_then(|value| value.checked_add(blob.len()))
                .ok_or(TrainError::InvalidModel("swarm artifact length overflow"))
        })?;
        let mut out = Vec::with_capacity(checked_model_capacity(32, &[payload_bytes])?);
        out.extend_from_slice(MINI_TRANSFORMER_SWARM_MODEL_MAGIC);
        out.extend_from_slice(
            &checked_u32(
                self.context_seq_len,
                "mini transformer swarm context_seq_len exceeds u32",
            )?
            .to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u32(
                self.workers.len(),
                "mini transformer swarm worker count exceeds u32",
            )?
            .to_le_bytes(),
        );
        out.extend_from_slice(
            &checked_u32(
                self.best_worker_index,
                "mini transformer swarm best worker exceeds u32",
            )?
            .to_le_bytes(),
        );
        out.extend_from_slice(&0_u32.to_le_bytes());
        out.extend_from_slice(&self.model_hash().to_le_bytes());
        for blob in worker_blobs {
            out.extend_from_slice(
                &checked_u64(blob.len(), "mini transformer worker blob exceeds u64")?.to_le_bytes(),
            );
            out.extend_from_slice(&blob);
        }
        Ok(out)
    }

    pub fn to_bytes(&self) -> Vec<u8> {
        self.try_to_bytes()
            .expect("mini transformer swarm model should fit on-disk format")
    }

    pub fn from_bytes(bytes: &[u8]) -> Result<Self, TrainError> {
        let header_len = MINI_TRANSFORMER_SWARM_MODEL_MAGIC.len() + 4 + 4 + 4 + 4 + 8;
        if bytes.len() < header_len {
            return Err(TrainError::InvalidModel("swarm artifact too short"));
        }
        if &bytes[..MINI_TRANSFORMER_SWARM_MODEL_MAGIC.len()] != MINI_TRANSFORMER_SWARM_MODEL_MAGIC
        {
            return Err(TrainError::InvalidModel("bad swarm magic"));
        }
        let mut offset = MINI_TRANSFORMER_SWARM_MODEL_MAGIC.len();
        let context_seq_len = read_u32_le(bytes, &mut offset)? as usize;
        let worker_count = read_u32_le(bytes, &mut offset)? as usize;
        let best_worker_index = read_u32_le(bytes, &mut offset)? as usize;
        let reserved = read_u32_le(bytes, &mut offset)?;
        let expected_model_hash = read_u64_le(bytes, &mut offset)?;
        if worker_count == 0 || best_worker_index >= worker_count || reserved != 0 {
            return Err(TrainError::InvalidModel("bad swarm header"));
        }

        let mut workers = Vec::with_capacity(worker_count);
        for _ in 0..worker_count {
            let blob_len = read_u64_le(bytes, &mut offset)? as usize;
            let blob_end = offset
                .checked_add(blob_len)
                .ok_or(TrainError::InvalidModel("swarm worker offset overflow"))?;
            let blob = bytes
                .get(offset..blob_end)
                .ok_or(TrainError::InvalidModel("swarm worker blob truncated"))?;
            workers.push(MiniTransformerMlpModel::from_bytes(blob)?);
            offset = blob_end;
        }
        if offset != bytes.len() {
            return Err(TrainError::InvalidModel("swarm artifact length mismatch"));
        }

        let model = Self::new(best_worker_index, workers)?;
        if model.context_seq_len != context_seq_len {
            return Err(TrainError::InvalidModel("swarm context hash mismatch"));
        }
        if model.model_hash() != expected_model_hash {
            return Err(TrainError::InvalidModel("swarm model hash mismatch"));
        }
        Ok(model)
    }

    pub fn to_expert_manifest(&self) -> Result<MiniTransformerMlpSwarmExpertManifest, TrainError> {
        Ok(MiniTransformerMlpSwarmExpertManifest {
            artifact_format: "nsrlswarm",
            artifact_magic: "NSRLSW1",
            artifact_byte_count: self.try_to_bytes()?.len(),
            model_id: MINI_TRANSFORMER_SWARM_MODEL_ID,
            tokenizer: BYTE_TOKENIZER_ID,
            context_seq_len: self.context_seq_len,
            worker_count: self.worker_count(),
            best_worker_index: self.best_worker_index,
            parameter_bytes: self.parameter_bytes(),
            model_hash: self.model_hash(),
            embedding_hash: self.embedding_hash(),
            attention_hash: self.attention_hash(),
            mlp_hash: self.mlp_hash(),
            output_head_hash: self.output_head_hash(),
            worker_model_hashes: self
                .workers
                .iter()
                .map(MiniTransformerMlpModel::model_hash)
                .collect(),
            worker_parameter_bytes: self
                .workers
                .iter()
                .map(mini_transformer_mlp_parameter_bytes)
                .collect(),
        })
    }

    pub fn parameter_bytes(&self) -> usize {
        self.workers
            .iter()
            .map(mini_transformer_mlp_parameter_bytes)
            .fold(0_usize, usize::saturating_add)
    }
}

fn mini_transformer_mlp_parameter_bytes(model: &MiniTransformerMlpModel) -> usize {
    model
        .embeddings
        .len()
        .saturating_add(model.position_embeddings.len())
        .saturating_mul(core::mem::size_of::<i16>())
        .saturating_add(model.q_weights.len())
        .saturating_add(model.k_weights.len())
        .saturating_add(model.v_weights.len())
        .saturating_add(model.o_weights.len())
        .saturating_add(model.up_weights.len())
        .saturating_add(model.gate_weights.len())
        .saturating_add(model.down_weights.len())
        .saturating_add(model.output_weights.len())
}

