    #[test]
    fn strict_lexeme_memory_decode_requires_observed_continuations_when_context_matches() {
        let memory = LexemeMemoryPriors::from_tokens(&[300, 301, 302, 350, 351, 352], 400, 2)
            .expect("memory");
        let mut logits = vec![0_i32; 400];
        let probabilities = vec![1_i16; 400];
        logits[350] = 10_000;
        logits[302] = 1;
        let decode = DecodeConfig {
            memory_context_order: 2,
            memory_min_context_order: 2,
            strict_memory: true,
            ..DecodeConfig::greedy()
        };

        let selection = select_lexeme_from_row(
            &logits,
            &probabilities,
            decode,
            0,
            &[300, 301],
            None,
            None,
            None,
            Some(&memory),
        );

        assert_eq!(selection.token, 302);
        assert!(selection.rejected_candidates.memory > 0);

        let pulsed_decode = DecodeConfig {
            memory_context_order: 2,
            memory_min_context_order: 2,
            strict_memory: true,
            strict_memory_on_steps: 1,
            strict_memory_off_steps: 1,
            ..DecodeConfig::greedy()
        };
        let released_selection = select_lexeme_from_row(
            &logits,
            &probabilities,
            pulsed_decode,
            1,
            &[300, 301],
            None,
            None,
            None,
            Some(&memory),
        );

        assert_eq!(released_selection.token, 350);
        assert_eq!(released_selection.rejected_candidates.memory, 0);

        let relaxed_selection = select_lexeme_from_row(
            &logits,
            &probabilities,
            decode,
            0,
            &[301, 300],
            None,
            None,
            None,
            Some(&memory),
        );

        assert_eq!(relaxed_selection.token, 350);
        assert_eq!(relaxed_selection.rejected_candidates.memory, 0);
    }

    #[test]
    fn lexeme_memory_priors_can_ignore_terminal_boundary_transitions() {
        let tokens = [300_u16, 301, 256, 3756, 301, 256, 400];
        let memory = LexemeMemoryPriors::from_tokens_with_terminal_tokens(&tokens, 4096, 2, &[256])
            .expect("memory");

        assert_eq!(
            memory.context_transition_probability_q15(&[300, 301], 256),
            i16::MAX as u16
        );
        assert_eq!(
            memory.context_transition_probability_q15(&[301, 256], 3756),
            0
        );
        assert_eq!(
            memory.context_transition_probability_q15(&[301, 256], 400),
            0
        );
    }

    #[test]
    fn lexeme_order_two_corpus_prior_prefers_phrase_continuations() {
        let tokens = [
            300_u16, 257, 258, 301, 257, 258, 302, 257, 258, 256, 257, 259,
        ];
        let priors = LexemeDecodePriors::from_tokens(&tokens, 512).expect("priors");
        let mut logits = vec![0_i32; 512];
        let probabilities = vec![1_i16; 512];
        logits[258] = 2_000;
        logits[259] = 1_950;
        let decode = DecodeConfig {
            corpus_prior: true,
            corpus_prior_logit_shift: 1,
            ..DecodeConfig::greedy()
        };

        assert_eq!(priors.observed_trigrams(), 10);
        assert_eq!(priors.transition_count(257, 258), 3);
        assert_eq!(priors.trigram_transition_count(256, 257, 259), 1);
        assert!(
            priors.context_transition_probability_q15(&[256, 257], 259, 2)
                > priors.context_transition_probability_q15(&[256, 257], 258, 2)
        );

        let bigram_selection = select_lexeme_from_row(
            &logits,
            &probabilities,
            decode,
            0,
            &[256, 257],
            Some(&priors),
            None,
            None,
            None,
        );
        let trigram_selection = select_lexeme_from_row(
            &logits,
            &probabilities,
            DecodeConfig {
                corpus_prior_order: 2,
                ..decode
            },
            0,
            &[256, 257],
            Some(&priors),
            None,
            None,
            None,
        );

        assert_eq!(bigram_selection.token, 258);
        assert_eq!(trigram_selection.token, 259);
    }

    #[test]
    fn lexeme_order_three_corpus_prior_prefers_longer_phrase_continuations() {
        let tokens = [
            300_u16, 257, 258, 259, 301, 257, 258, 259, 302, 257, 258, 259, 256, 257, 258, 260,
        ];
        let priors = LexemeDecodePriors::from_tokens(&tokens, 512).expect("priors");
        let mut logits = vec![0_i32; 512];
        let probabilities = vec![1_i16; 512];
        logits[259] = 2_000;
        logits[260] = 1_950;
        let decode = DecodeConfig {
            corpus_prior: true,
            corpus_prior_logit_shift: 1,
            ..DecodeConfig::greedy()
        };

        assert_eq!(priors.transition_count(258, 259), 3);
        assert_eq!(priors.trigram_transition_count(257, 258, 259), 3);
        assert_eq!(priors.quadgram_transition_count(256, 257, 258, 260), 1);
        assert!(
            priors.context_transition_probability_q15(&[256, 257, 258], 260, 3)
                > priors.context_transition_probability_q15(&[256, 257, 258], 259, 3)
        );

        let trigram_selection = select_lexeme_from_row(
            &logits,
            &probabilities,
            DecodeConfig {
                corpus_prior_order: 2,
                ..decode
            },
            0,
            &[256, 257, 258],
            Some(&priors),
            None,
            None,
            None,
        );
        let quadgram_selection = select_lexeme_from_row(
            &logits,
            &probabilities,
            DecodeConfig {
                corpus_prior_order: 3,
                ..decode
            },
            0,
            &[256, 257, 258],
            Some(&priors),
            None,
            None,
            None,
        );

        assert_eq!(trigram_selection.token, 259);
        assert_eq!(quadgram_selection.token, 260);
    }

    #[test]
    fn linear_backward_trace_updates_weights_and_transposes_gradient() {
        let trace = run_linear_backward_smoke(LinearBackwardConfig::default()).expect("linear bw");

        assert_eq!(trace.scaled_grad_output_i32, [8192, -6144, 512]);
        assert_eq!(trace.grad_input_q15, [3968, -5056, 832, -1472]);
        assert_eq!(trace.output_before_q15, [17408, -19968, 640]);
        assert_eq!(trace.output_after_q15, [-26112, 28416, -384]);
        assert_eq!(
            trace.weights_after_i8,
            [
                -5, 2, -1, 1, //
                5, 1, 1, 1, //
                1, 1, -3, 1,
            ]
        );
        assert_eq!(trace.update_stats.gradient_saturation_count, 0);
        assert_eq!(trace.update_stats.zero_delta_count, 3);
        assert_eq!(trace.update_stats.weight_delta_l1, 27);
        assert_ne!(trace.initial_weight_hash, trace.final_weight_hash);
    }

    #[test]
    fn linear_backward_trace_is_byte_stable() {
        let left = run_linear_backward_smoke(LinearBackwardConfig::default())
            .expect("left")
            .to_json_line();
        let right = run_linear_backward_smoke(LinearBackwardConfig::default())
            .expect("right")
            .to_json_line();

        assert_eq!(left, right);
        assert!(left.contains("\"schema\":\"nsrl.training_linear_backward_trace.v1\""));
        assert!(left.contains("\"intermediate\":\"i64_outer_product\""));
        assert!(left.contains("\"scaled_grad_output_i32\":[8192,-6144,512]"));
    }

    #[test]
    fn gated_mlp_backward_trace_updates_all_matrices() {
        let trace = run_gated_mlp_backward_smoke(LinearBackwardConfig {
            learning_rate: 1,
            learning_rate_shift: 20,
        })
        .expect("gated mlp bw");

        assert_ne!(trace.up_before_i8, trace.up_after_i8);
        assert_ne!(trace.gate_before_i8, trace.gate_after_i8);
        assert_ne!(trace.down_before_i8, trace.down_after_i8);
        assert_ne!(trace.output_before_q15, trace.output_after_q15);
        assert_ne!(trace.initial_weight_hash, trace.final_weight_hash);
        assert_ne!(trace.output_hash_before, trace.output_hash_after);
        assert_eq!(trace.update_stats.gradient_saturation_count(), Some(0));
        assert!(trace.update_stats.weight_delta_l1().unwrap() > 0);
        assert!(trace.update_stats.up.weight_delta_l1 > 0);
        assert!(trace.update_stats.gate.weight_delta_l1 > 0);
        assert!(trace.update_stats.down.weight_delta_l1 > 0);
    }

